local function beast(ctx,e) for _,tag in ipairs(ctx:card_definition(ctx:entity(e).card_id).tags) do if tag=="beast" or tag=="all" then return true end end return false end
return { api_version=1, id="EX1_539", name="Kill Command", text="Deal $3 damage. If you control a Beast, deal\n$5 damage instead.", set="LEGACY", type="spell", class="hunter", cost=3, target_mode="required", targets=function(ctx) return ctx:characters() end, on_play=function(ctx,self,target) local amount=3; for _,e in ipairs(ctx:friendly_minions(self)) do if beast(ctx,e) then amount=5 break end end; ctx:damage(target,amount) end }
